import type { ReactNode } from 'react';
import { cn } from '../../utils';

export interface EmptyStateProps {
  /** An illustration from `illustrations.tsx`, or any drawn SVG. */
  art?: ReactNode;
  title: string;
  /** One line on why it is empty and what fills it. */
  description?: string;
  /** A single action. Omit when the user cannot do anything about it. */
  action?: ReactNode;
  size?: 'sm' | 'default';
  className?: string;
}

/**
 * The state a trading UI spends most of its life in.
 *
 * Before the open, between sessions, on a fresh account, every list here is
 * empty - so an empty state is not a corner case to apologise for, it is a
 * primary screen. Each one names what is missing and what would fill it,
 * rather than saying "no data".
 */
export function EmptyState({
  art,
  title,
  description,
  action,
  size = 'default',
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center gap-3 text-center',
        size === 'sm' ? 'px-4 py-6' : 'px-6 py-10',
        className,
      )}
    >
      {art && <div className={cn('opacity-90', size === 'sm' && 'scale-75')}>{art}</div>}
      <div className="flex max-w-[34ch] flex-col gap-1">
        <p className="text-foreground text-xs font-semibold tracking-wide">{title}</p>
        {description && (
          <p className="text-muted-foreground text-[11px] leading-relaxed">{description}</p>
        )}
      </div>
      {action}
    </div>
  );
}

import type { SVGProps } from 'react';
import { cn } from '../../utils';

/**
 * Empty-state illustrations.
 *
 * One drawn family, not five unrelated pictures: every one is built from the
 * same vocabulary - hairline rules at the same rhythm, a dashed reference
 * line, and small tick marks - so an empty book and an empty blotter read as
 * two states of the same instrument.
 *
 * All strokes are `currentColor` at graded opacity, so the caller sets one
 * colour and the drawing stays in the theme. 1.25px stroke throughout, matching
 * the hairline weight of the components they sit inside.
 */

type IllustrationProps = SVGProps<SVGSVGElement>;

function Frame({ className, children, ...props }: IllustrationProps) {
  return (
    <svg
      viewBox="0 0 120 80"
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={cn('h-20 w-auto text-muted-foreground', className)}
      {...props}
    >
      {children}
    </svg>
  );
}

/** Empty ladder: rows thinning out, with a gap where the touch would be. */
export function EmptyBookArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={`a${i}`} opacity={0.18 + i * 0.07}>
          <rect
            x={18}
            y={8 + i * 10}
            width={84 - i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
      {/* The spread. The one place the drawing breaks rhythm, because that is
          the thing the component is for. */}
      <line
        x1={10}
        y1={43}
        x2={110}
        y2={43}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.55}
      />
      {[0, 1, 2].map((i) => (
        <g key={`b${i}`} opacity={0.25 - i * 0.07}>
          <rect
            x={18}
            y={52 + i * 10}
            width={72 + i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
    </Frame>
  );
}

/** Empty tape: a paper strip running out, prints trailing to nothing. */
export function EmptyTapeArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <rect
        x={14}
        y={16}
        width={92}
        height={48}
        rx={3}
        stroke="currentColor"
        strokeWidth={1.25}
        opacity={0.35}
      />
      {[0, 1, 2, 3].map((i) => (
        <g key={i} opacity={0.4 - i * 0.09}>
          <rect x={24} y={26 + i * 10} width={18} height={4} rx={1.5} fill="currentColor" />
          <rect x={50} y={26 + i * 10} width={22} height={4} rx={1.5} fill="currentColor" />
          <rect x={80} y={26 + i * 10} width={14} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
      {/* Sprocket perforations, so it reads as tape rather than a table. */}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={9} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={111} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
    </Frame>
  );
}

/** No positions: a flat book — axis with nothing plotted against it. */
