}

/** Empty watchlist: rows waiting, each with a flat line where a trend goes. */
export function EmptyWatchlistArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={i} opacity={0.4 - i * 0.1}>
          <rect x={14} y={18 + i * 16} width={20} height={4} rx={1.5} fill="currentColor" />
          <line
            x1={44}
            y1={20 + i * 16}
            x2={78}
            y2={20 + i * 16}
            stroke="currentColor"
            strokeWidth={1.25}
            strokeDasharray="3 4"
          />
          <rect x={88} y={18 + i * 16} width={18} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
    </Frame>
  );
}

/** Nothing to chart: axes with a dashed, featureless series. */
export function EmptyChartArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <line x1={16} y1={12} x2={16} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={16} y1={62} x2={106} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <path
        d="M16 48 L38 38 L58 44 L78 28 L106 34"
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
      />
      {[0, 1, 2, 3].map((i) => (
        <line
          key={i}
          x1={30 + i * 22}
          y1={62}
          x2={30 + i * 22}
          y2={65}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
        />
      ))}
    </Frame>
  );
}

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Loading states.
 *
 * Each skeleton is shaped like the thing it replaces - the ladder skeleton has
 * a spread row, the chart skeleton has an axis and a volume pane - so the
 * layout does not jump when real data lands and the eye already knows where to
 * look. A generic grey box would be cheaper and would cost a reflow every time.
 *
 * The pulse is opacity only, and stops under `prefers-reduced-motion`.
 */
export function Skeleton({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="skeleton"
      className={cn('bg-muted-foreground/15 animate-shimmer rounded-sm', className)}
      {...props}
    />
  );
}

/** Deterministic widths: random ones would re-roll on every render. */
const LADDER_WIDTHS = [62, 48, 74, 55, 68, 44, 80, 51, 66, 58, 72, 46];

export function OrderBookSkeleton({ depth = 8, className }: { depth?: number; className?: string }) {
  const row = (key: string, i: number, side: 'bid' | 'ask') => (
    <div key={key} className="flex items-center gap-2 px-2.5 py-[5px]">
      <Skeleton
        className={cn('h-2.5 flex-1', side === 'bid' ? 'bg-up/15' : 'bg-down/15')}
        style={{ maxWidth: `${LADDER_WIDTHS[i % LADDER_WIDTHS.length]}%` }}
      />
      <Skeleton className="h-2.5 w-10" />
      <Skeleton className="h-2.5 w-8" />
    </div>
  );

  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-10" />
        <Skeleton className="ml-auto h-2 w-8" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`a${i}`, i, 'ask'))}
      <div className="bg-muted my-0.5 flex items-center justify-between border-y px-2.5 py-2">
        <Skeleton className="h-2.5 w-16" />
        <Skeleton className="h-2.5 w-20" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`b${i}`, i + 3, 'bid'))}
    </div>
  );
}

export function TradeTapeSkeleton({ rows = 10, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-8" />
        <Skeleton className="ml-auto h-2 w-10" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="grid grid-cols-3 gap-2 px-2.5 py-[5px]">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-2.5 w-12 justify-self-end" />
          <Skeleton className="h-2.5 w-8 justify-self-end" />
        </div>
      ))}
    </div>
  );
}

/** Candle bars at varied heights around a baseline, plus axis and volume. */
const CANDLE_HEIGHTS = [38, 52, 44, 61, 49, 70, 57, 42, 66, 51, 74, 46, 59, 68, 40, 55, 63, 47];

export function CandleChartSkeleton({
  height = 320,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <div
      className={cn('flex w-full flex-col gap-2 p-2', className)}
      style={{ height }}
      aria-hidden="true"
    >
      <div className="flex min-h-0 flex-1 items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1"
            style={{ height: `${h}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex h-[16%] items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1 opacity-60"
            style={{ height: `${h * 0.7}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex justify-between pr-14">
        {Array.from({ length: 6 }, (_, i) => (
          <Skeleton key={i} className="h-2 w-8" />
        ))}
      </div>
    </div>
  );
}

export function TableSkeleton({
  rows = 4,
  columns = 6,
  className,
}: {
  rows?: number;
  columns?: number;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-4 border-b px-2.5 py-2">
        {Array.from({ length: columns }, (_, i) => (
          <Skeleton key={i} className={cn('h-2', i === 0 ? 'w-14' : 'flex-1')} />
        ))}
      </div>
      {Array.from({ length: rows }, (_, r) => (
        <div key={r} className="flex gap-4 border-b px-2.5 py-2.5">
          {Array.from({ length: columns }, (_, i) => (
            <Skeleton key={i} className={cn('h-2.5', i === 0 ? 'w-14' : 'flex-1')} />
          ))}
        </div>
      ))}
    </div>
  );
}

export function WatchlistSkeleton({ rows = 6, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-2.5 border-b px-2.5 py-2">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-4 w-14" />
          <Skeleton className="ml-auto h-2.5 w-12" />
          <Skeleton className="h-2.5 w-10" />
        </div>
      ))}
    </div>
  );
}

import type { ReactNode } from 'react';
import { formatPrice } from '../../format';
import type { Quote } from '../../types';
import { cn } from '../../utils';
import { Delta } from './delta';
import { EmptyState } from './empty-state';
import { EmptyWatchlistArt } from './illustrations';
import { WatchlistSkeleton } from './skeletons';
import { Sparkline } from './sparkline';

export interface WatchlistProps {
  quotes: Quote[];
  /** Symbol to mark as current. */
  selected?: string;
  onSelect?: (quote: Quote) => void;
  pricePrecision?: number;
  showSparkline?: boolean;
  /** Absolute change instead of percent. */
  showAbsolute?: boolean;
  /** Shows a row-shaped skeleton instead of the quotes. */
  loading?: boolean;
  /** Rendered in the empty state - typically an "add symbol" control. */
  emptyAction?: ReactNode;
  className?: string;
}

/**
 * Symbol list with price, change and an inline trend.
 *
 * Rows are real buttons in a listbox, not clickable divs: the list is tabbable,
 * the current row is announced via `aria-selected`, and the sparkline is hidden
 * from assistive tech because the number beside it already says the same thing.
 */
export function Watchlist({
  quotes,
  selected,
  onSelect,
  pricePrecision = 2,
  showSparkline = true,
  showAbsolute = false,
  loading = false,
  emptyAction,
  className,
}: WatchlistProps) {
  if (loading) return <WatchlistSkeleton className={className} />;

  if (quotes.length === 0) {
    return (
      <EmptyState
        className={className}
        art={<EmptyWatchlistArt />}
        title="Nothing on the list"
        description="Add the instruments you want to keep an eye on and their price, change and trend show up here."
        action={emptyAction}
      />
    );
  }

  return (
    <div
      role="listbox"
      aria-label="Watchlist"
      className={cn('flex flex-col', className)}
    >
      {quotes.map((quote) => {
        const change = quote.last - quote.prevClose;
        const isSelected = quote.symbol === selected;
        return (
          <button
            key={quote.symbol}
            type="button"
            role="option"
            aria-selected={isSelected}
            className={cn(
              'hover:bg-accent focus-visible:ring-ring grid w-full cursor-pointer grid-cols-[minmax(52px,1fr)_58px_minmax(60px,auto)_minmax(66px,auto)] items-center gap-2.5 border-b px-2.5 py-1.5 text-left outline-none focus-visible:ring-2',
              isSelected && 'bg-primary/10 shadow-[inset_2px_0_0_var(--primary)]',
            )}
            onClick={() => onSelect?.(quote)}
          >
            <span className="text-xs font-semibold tracking-wide">{quote.symbol}</span>
            {showSparkline ? (
              <Sparkline
                data={quote.history ?? []}
                baseline={quote.prevClose}
                width={58}
                height={20}
              />
            ) : (
              <span />
            )}
            <span className="text-right font-mono text-xs tabular-nums">
              {formatPrice(quote.last, pricePrecision)}
            </span>
            <span className="flex justify-end">
              <Delta
                value={showAbsolute ? change : undefined}
                percent={showAbsolute ? undefined : change / quote.prevClose}
                precision={pricePrecision}
                icon={false}
              />
            </span>
          </button>
        );
      })}
    </div>
  );
}

import { TrendingDownIcon, TrendingUpIcon } from 'lucide-react';
import { directionOf, formatPercent, formatSigned } from '../../format';
import { cn } from '../../utils';
import { Badge } from '../ui/badge';

export interface DeltaProps {
  /** Absolute change. Omit to show the percentage alone. */
  value?: number;
  /** Change as a ratio (0.0421 renders as +4.21%). */
  percent?: number;
  precision?: number;
  /** Boxed badge instead of bare text. */
  pill?: boolean;
  /** Prefix with a trend icon. */
  icon?: boolean;
  className?: string;
}

/**
 * The change indicator.
 *
 * Direction is carried three ways at once - color, an icon, and an explicit
 * sign. Color alone fails a colorblind reader; in a grayscale screenshot or a
 * printed risk report it fails everyone.
 */
export function Delta({
  value,
  percent,
  precision = 2,
  pill = false,
  icon = true,
  className,
}: DeltaProps) {
  const basis = value ?? percent ?? 0;
  const direction = directionOf(basis);

  const parts: string[] = [];
  if (value !== undefined) parts.push(formatSigned(value, precision));
  if (percent !== undefined) {
    parts.push(
      value !== undefined
        ? `(${formatPercent(percent, precision, false)})`
        : formatPercent(percent, precision),
    );
  }

  const Icon =
    direction === 'up' ? TrendingUpIcon : direction === 'down' ? TrendingDownIcon : null;
  const tone = direction === 'up' ? 'text-up' : direction === 'down' ? 'text-down' : 'text-flat';

  const body = (
    <>
      {icon && Icon && <Icon className="size-3 shrink-0" aria-hidden="true" />}
      <span className="sr-only">
        {direction === 'up' ? 'up' : direction === 'down' ? 'down' : 'unchanged'}{' '}
      </span>
      {parts.join(' ')}
    </>
  );

  if (pill) {
    return (
      <Badge variant={direction} className={cn('font-mono tabular-nums', className)}>
        {body}
      </Badge>
    );
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 font-mono text-xs font-semibold tabular-nums whitespace-nowrap',
        tone,
        className,
      )}
    >
      {body}
    </span>
  );
}

import { useId, useMemo } from 'react';
import { cn } from '../../utils';

export interface SparklineProps {
  data: number[];
  width?: number;
  height?: number;
  /** Reference level. Direction coloring and the optional rule use it. */
  baseline?: number;
  strokeWidth?: number;
  /** Gradient fill under the line. */
  area?: boolean;
  /** Dashed rule at the baseline. */
  showBaseline?: boolean;
  /** Dot on the final point. */
  markLast?: boolean;
  /** Force a color instead of deriving it from last-vs-baseline. */
  color?: string;
  className?: string;
  'aria-label'?: string;
}

/**
 * Inline trend line.
 *
 * SVG rather than canvas: these appear dozens at a time in a watchlist, where
 * one canvas context per row is wasteful, SVG scales for free, and the line
 * stays crisp at any device pixel ratio without a redraw.
 */
export function Sparkline({
  data,
  width = 72,
  height = 22,
  baseline,
  strokeWidth = 1.25,
  area = true,
  showBaseline = false,
  markLast = false,
  color,
  className,
  ...aria
}: SparklineProps) {
  const gradientId = useId();

  const geometry = useMemo(() => {
    const points = data.filter(Number.isFinite);
    if (points.length < 2) return null;

    const base = baseline ?? points[0];
    let min = Math.min(...points);
    let max = Math.max(...points);
    // Keep the baseline inside the viewport so the fill reads correctly.
    if (showBaseline || baseline !== undefined) {
      min = Math.min(min, base);
      max = Math.max(max, base);
    }
    const span = max - min || Math.abs(max) * 0.01 || 1;
    const pad = strokeWidth + (markLast ? 2 : 0);
    const innerH = Math.max(1, height - pad * 2);

    const x = (i: number) => (i / (points.length - 1)) * width;
    const y = (v: number) => pad + innerH - ((v - min) / span) * innerH;

    const line = points.map((v, i) => `${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');
    const last = points[points.length - 1];

    return {
      line,
      fill: `M0,${height} L${line.split(' ').join(' L')} L${width},${height} Z`,
      baselineY: y(base),
      lastX: x(points.length - 1),
      lastY: y(last),
      direction: last >= base ? 'up' : 'down',
    } as const;
  }, [data, baseline, width, height, strokeWidth, showBaseline, markLast]);

  if (!geometry) {
    return <svg className={className} width={width} height={height} aria-hidden="true" />;
  }

  const stroke = color ?? `var(--${geometry.direction})`;

  return (
    <svg
      className={cn('block overflow-visible', className)}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      role={aria['aria-label'] ? 'img' : 'presentation'}
      aria-label={aria['aria-label']}
      aria-hidden={aria['aria-label'] ? undefined : true}
    >
      {area && (
        <>
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={stroke} stopOpacity={0.3} />
              <stop offset="100%" stopColor={stroke} stopOpacity={0} />
            </linearGradient>
          </defs>
          <path d={geometry.fill} fill={`url(#${gradientId})`} stroke="none" />
        </>
      )}
      {showBaseline && (
        <line
          x1={0}
          x2={width}
          y1={geometry.baselineY}
          y2={geometry.baselineY}
          stroke="var(--border)"
          strokeWidth={1}
          strokeDasharray="2 2"
        />
      )}
      <polyline
        points={geometry.line}
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      {markLast && (
        <circle cx={geometry.lastX} cy={geometry.lastY} r={strokeWidth + 0.9} fill={stroke} />
      )}
    </svg>
  );
}

import { Slot } from '@radix-ui/react-slot';
